<?php
use PHPUnit\Framework\TestCase;final class GovernanceDashboardApiTest extends TestCase{public function test_anonymous_is_denied():void{wp_set_current_user(0);$r=rest_do_request(new WP_REST_Request('GET','/zincelestial/v1/governance-dashboard'));$this->assertContains($r->get_status(),[401,403]);}public function test_authorized_response_projects_no_payload():void{$id=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($id);$req=new WP_REST_Request('GET','/zincelestial/v1/governance-dashboard');$req->set_param('limit',10);$r=rest_do_request($req);$this->assertSame(200,$r->get_status());$data=$r->get_data();$this->assertArrayHasKey('summary',$data);foreach($data['timeline'] as $row)$this->assertArrayNotHasKey('payload',$row);}}
